BEGIN;
ALTER TABLE legal_wiki.lawyer_reviews ADD COLUMN IF NOT EXISTS approval_digest text CHECK(approval_digest IS NULL OR length(approval_digest)=64);
CREATE OR REPLACE VIEW legal_wiki.qualified_verified_revisions WITH(security_invoker=true,security_barrier=true) AS SELECT v.* FROM legal_wiki.verified_revisions v JOIN legal_wiki.wiki_revisions r ON r.id=v.id AND r.tenant=v.tenant JOIN LATERAL (SELECT lr.* FROM legal_wiki.lawyer_reviews lr WHERE lr.tenant=r.tenant AND lr.revision_id=r.id ORDER BY lr.reviewed_at DESC,lr.id DESC LIMIT 1) lr ON true JOIN public.lawyer_verifications lv ON lv.tenant=r.tenant AND lv.user_id=lr.reviewer_id JOIN public.users u ON u.id=lv.user_id AND u.tenant=lv.tenant WHERE lv.status='approved' AND lv.checked_at IS NOT NULL AND NULLIF(btrim(lv.checked_by),'') IS NOT NULL AND lr.credential_ref='lawyer-verification:'||lv.user_id AND lr.reviewer_id<>r.author_id AND lr.approval_digest=encode(sha256(convert_to(jsonb_build_array(r.title,r.summary,r.body_markdown,r.legal_as_of,r.version)::text,'UTF8')),'hex');
COMMIT;
